Add-Type -TypeDefinition $src -Language CSharp
$tok = ([Cred]::Read("Supabase CLI:access-token")).Trim([char]0).Trim()
$H = @{ Authorization = "Bearer $tok"; "Content-Type" = "application/json" }
$prod="jaumyfyeueayibbxunxc"; $stg="ofgjllzbxrydhkrfnhan"
function Q($ref,$sql){ Invoke-RestMethod -Uri "https://api.supabase.com/v1/projects/$ref/database/query" -Headers $H -Method Post -Body (@{query=$sql}|ConvertTo-Json -Compress) }

$skip = @('mia_user_telemetry','mia_telemetry_sessions','scanner_telemetry','user_activity_log','user_sessions',
 'financial_audit_log','estoque_audit_log','employee_audit_log','expedicao_logs','etiquetas_qr_eventos',
 'alertas_estoque','noaa_messages','noaa_llm_calls','noaa_rate_limits','noaa_whatsapp_sessions','chat_messages',
 'pronta_entrega_logs','bkp_reset_setores_fabrica_20260603_etiquetas','mia_query_logs','mia_route_transitions','noaa_message_status')
$cap = 2000

# mapa de colunas insertaveis (exclui geradas e identity ALWAYS)
$colsMap = @{}
(Q $stg "select table_name, string_agg(quote_ident(column_name),',' order by ordinal_position) cols from information_schema.columns where table_schema='public' and is_generated='NEVER' and (is_identity<>'YES' or identity_generation is distinct from 'ALWAYS') group by table_name") | ForEach-Object { $colsMap[$_.table_name] = $_.cols }

$tables = @(Q $prod "select relname, n_live_tup from pg_stat_user_tables where schemaname='public' and n_live_tup>0 order by n_live_tup")
Write-Output ("tabelas com dados: " + $tables.Count)
$done=0; $failed=0
foreach($row in $tables){
  $t = $row.relname
  if ($skip -contains $t) { Write-Output ("SKIP $t ("+$row.n_live_tup+")"); continue }
  $cols = $colsMap[$t]
  if (-not $cols) { Write-Output ("sem cols: $t"); continue }
  foreach($lim in @([Math]::Min([int]$row.n_live_tup,$cap), 500)){
    try {
      $j = (@(Q $prod "select coalesce(json_agg(x),'[]')::text j from (select * from public.""$t"" order by ctid desc limit $lim) x")[0]).j
      $jEsc = $j.Replace("'","''")
      $ins = "set session_replication_role=replica; insert into public.""$t"" ($cols) select $cols from json_populate_recordset(null::public.""$t"", '$jEsc') on conflict do nothing;"
      Q $stg $ins | Out-Null
      $c = (@(Q $stg "select count(*) c from public.""$t""")[0]).c
      Write-Output ("OK $t -> $c / $($row.n_live_tup)")
      $done++
      break
    } catch {
      $m = if($_.ErrorDetails){$_.ErrorDetails.Message}else{$_.Exception.Message}
      if ($lim -eq 500) { Write-Output ("FALHA $t: "+$m.Substring(0,[Math]::Min(160,$m.Length))); $failed++ }
    }
  }
}
